//! Entity identity: `dat_id` and `dat_txn` (UUIDv7, generated by the client).
//!
//! Layout (RFC 9562, section 5.7), most significant bit first:
//!
//! ```text
//! unix_ts_ms (48) | ver = 0b0111 (4) | counter (12) | var = 0b10 (2) | random (62)
//! ```
//!
//! The 12-bit field is a counter (RFC 9562, section 6.2, method 1), so ids made
//! by one generator are strictly increasing even within one millisecond or when
//! the wall clock steps back. Each new millisecond seeds the counter with 11
//! random bits, leaving at least 2048 values before it overflows; on overflow
//! the timestamp moves one millisecond ahead of the wall clock.

use std::fmt;
use std::sync::Mutex;
use std::time::{SystemTime, UNIX_EPOCH};

use uuid::Uuid;

const MAX_MS: u64 = (1 << 48) - 1;
const MAX_COUNTER: u64 = (1 << 12) - 1;
const VERSION: u128 = 0x7;
const VARIANT: u128 = 0b10;

/// Why no id could be made.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IdError {
    /// The clock returned a value outside the 48-bit timestamp.
    InvalidClock(i64),
    /// The counter overflowed at the largest timestamp.
    TimestampExhausted,
}

impl fmt::Display for IdError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            IdError::InvalidClock(ms) => {
                write!(
                    f,
                    "clock value {ms} does not fit the 48-bit UUIDv7 timestamp"
                )
            }
            IdError::TimestampExhausted => f.write_str("48-bit UUIDv7 timestamp exhausted"),
        }
    }
}

impl std::error::Error for IdError {}

type ClockFn = dyn Fn() -> i64 + Send + Sync;
type RandFn = dyn Fn(u32) -> u64 + Send + Sync;

struct Counter {
    last_ms: Option<u64>,
    counter: u64,
}

/// Thread-safe UUIDv7 source, monotonic within one instance.
pub struct IdGenerator {
    clock_ms: Box<ClockFn>,
    randbits: Box<RandFn>,
    state: Mutex<Counter>,
}

impl fmt::Debug for IdGenerator {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("IdGenerator").finish_non_exhaustive()
    }
}

impl Default for IdGenerator {
    fn default() -> Self {
        Self::new()
    }
}

/// Milliseconds since the Unix epoch from the system clock.
#[must_use]
pub fn system_ms() -> i64 {
    match SystemTime::now().duration_since(UNIX_EPOCH) {
        Ok(d) => i64::try_from(d.as_millis()).unwrap_or(i64::MAX),
        Err(before) => -i64::try_from(before.duration().as_millis()).unwrap_or(i64::MAX),
    }
}

fn os_randbits(bits: u32) -> u64 {
    let value = getrandom::u64().expect("the operating system random source failed");
    value & ((1_u64 << bits) - 1)
}

impl IdGenerator {
    /// A generator over the system clock and the operating system's random source.
    #[must_use]
    pub fn new() -> Self {
        Self::with_sources(system_ms, os_randbits)
    }

    /// A generator over injected sources: `clock_ms` returns Unix milliseconds,
    /// `randbits(n)` returns a uniformly random value below `2^n` (`n` is 11 or 62).
    pub fn with_sources(
        clock_ms: impl Fn() -> i64 + Send + Sync + 'static,
        randbits: impl Fn(u32) -> u64 + Send + Sync + 'static,
    ) -> Self {
        Self {
            clock_ms: Box::new(clock_ms),
            randbits: Box::new(randbits),
            state: Mutex::new(Counter {
                last_ms: None,
                counter: 0,
            }),
        }
    }

    /// The next id.
    ///
    /// # Errors
    ///
    /// [`IdError::InvalidClock`] when the clock is outside `[0, 2^48)`, and
    /// [`IdError::TimestampExhausted`] when the counter overflows at the largest
    /// timestamp.
    pub fn generate(&self) -> Result<Uuid, IdError> {
        let (ms, counter) = {
            let mut state = self
                .state
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            let raw = (self.clock_ms)();
            let ms = u64::try_from(raw)
                .ok()
                .filter(|ms| *ms <= MAX_MS)
                .ok_or(IdError::InvalidClock(raw))?;
            match state.last_ms {
                Some(last) if ms <= last => {
                    if state.counter < MAX_COUNTER {
                        state.counter += 1;
                    } else if last == MAX_MS {
                        return Err(IdError::TimestampExhausted);
                    } else {
                        state.last_ms = Some(last + 1);
                        state.counter = (self.randbits)(11);
                    }
                }
                _ => {
                    state.last_ms = Some(ms);
                    state.counter = (self.randbits)(11);
                }
            }
            (state.last_ms.unwrap_or(ms), state.counter)
        };
        let value = (u128::from(ms) << 80)
            | (VERSION << 76)
            | (u128::from(counter) << 64)
            | (VARIANT << 62)
            | u128::from((self.randbits)(62));
        Ok(Uuid::from_u128(value))
    }
}

/// True for an RFC 9562 version 7 UUID.
#[must_use]
pub fn is_uuid7(value: Uuid) -> bool {
    value.get_version_num() == 7 && value.get_variant() == uuid::Variant::RFC4122
}

/// Unix time in milliseconds stored in a UUIDv7, `None` for any other UUID.
#[must_use]
pub fn timestamp_ms(value: Uuid) -> Option<u64> {
    is_uuid7(value).then(|| u64::try_from(value.as_u128() >> 80).unwrap_or(u64::MAX))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn system_ids_are_uuid7_and_strictly_increasing() {
        let generate = IdGenerator::new();
        let ids: Vec<Uuid> = (0..5000).map(|_| generate.generate().unwrap()).collect();
        assert!(ids.iter().all(|id| is_uuid7(*id)));
        assert!(ids.windows(2).all(|w| w[0] < w[1]));
        let now = u64::try_from(system_ms()).unwrap();
        assert!(timestamp_ms(ids[0]).unwrap().abs_diff(now) < 60_000);
    }

    #[test]
    fn only_uuid7_has_a_timestamp() {
        assert_eq!(timestamp_ms(Uuid::nil()), None);
        assert!(!is_uuid7(Uuid::max()));
    }

    #[test]
    fn os_random_values_fit_the_requested_width() {
        assert!((0..1000).all(|_| os_randbits(11) < 1 << 11));
    }
}
